// M6 - Freigabe. Baut je Bewerbung genau eine Zeile fuer den Tab M6_Freigabe.
// Bereits getroffene Entscheidungen werden NIE ueberschrieben.
//
// Dynamisch: keine fest verdrahteten stellen_id. Uebernommen wird jede Agentur,
// die M4 und M5 abgeschlossen hat und alle Pflichtangaben mitbringt.
//
// Das Datum der finalen PDF erzeugt AUSSCHLIESSLICH M5B, und zwar erst im
// FINAL-Lauf. M6 berechnet dafuer nichts und loest FINAL auch nicht mehr aus.
//
// Geaendert am 10.08.2026: Frueher setzte diese Stelle bei jeder JA-Zeile
// _final_ausloesen = true und startete damit M5B FINAL. Das erzeugte die
// datierte Endfassung bereits im Moment der inhaltlichen Freigabe. Zwischen
// Freigabe und tatsaechlichem Versand koennen aber Tage liegen - die Bewerbung
// trug dann ein zu altes Datum. Ausserdem lief FINAL bei JEDEM Lauf erneut,
// weil es keine Wiederholungssperre gab.
// FINAL gehoert deshalb an die Versandfreigabe in M7. M6 entscheidet nur
// inhaltlich und haelt den Zielpfad fest.
//
// Freigabesperre: Eine Zeile wird nur FREIGEGEBEN, wenn im Tab M6_Berater
// berater_status = FERTIG steht. UNSICHER, FEHLER oder eine fehlende
// Beraterzeile fuehren bei JA zu m6_status = FEHLER. Damit kann keine
// zweifelhafte Beratung M5B FINAL erreichen.

const BETREFF = 'Initiativbewerbung im Bereich KI und Automatisierungen';
const VORSCHAU_ORDNER = '/showcase/files/vorschau';
const FINAL_ORDNER = '/showcase/files/final';

function c(v) { return String(v == null ? '' : v).replace(/ /g, ' ').replace(/\s+/g, ' ').trim(); }
function mehrzeilig(v) { return String(v == null ? '' : v).replace(/ /g, ' ').trim(); }
function istEmail(v) { return /^[^\s@]+@[^\s@]+\.[A-Za-z]{2,}$/.test(c(v)); }

// Zeitstempel der Entscheidung. Das ist NICHT das Datum der finalen PDF.
function berlinZeit(d) {
  return new Intl.DateTimeFormat('de-DE', {
    timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
  }).format(d);
}

const agentur = $('Agentursuche laden').all().map(i => i.json || {});

let pdfDateien = [];
try {
  pdfDateien = $('Vorschau-PDFs pruefen').all().map(i => i.json || {}).filter(j => c(j.fileName));
} catch (e) { pdfDateien = []; }

let bisher = [];
let sheetInitialisiert = false;
try {
  const roh = $('Bisherige Freigaben laden').all().map(i => i.json || {});
  bisher = roh.filter(j => c(j.stellen_id));
  sheetInitialisiert = roh.some(j => Object.keys(j).length > 0);
} catch (e) { bisher = []; sheetInitialisiert = false; }

// Beraterzeilen. Faellt der Lesenode aus oder ist der Tab leer, bleibt die Liste
// leer und die Freigabe wird blockiert - der sichere Ausgang.
let beratungen = [];
try {
  beratungen = $('Beratungen laden').all().map(i => i.json || {}).filter(j => c(j.stellen_id));
} catch (e) { beratungen = []; }

const jetzt = new Date();
const zeilen = [];
const uebersprungen = [];

// Dynamische Kandidatenauswahl statt fester Liste
const gesehen = {};
for (const r of agentur) {
  const id = c(r.stellen_id);
  if (!id) continue;
  if (c(r.quelle).toLowerCase() !== 'agentursuche') continue;
  if (c(r.record_type).toUpperCase() !== 'COMPANY') continue;
  gesehen[id] = (gesehen[id] || 0) + 1;
}

for (const id of Object.keys(gesehen)) {
  if (gesehen[id] > 1) { uebersprungen.push(id + ': mehrfach in Agentursuche vorhanden (' + gesehen[id] + 'x)'); continue; }
  const r = agentur.find(x => c(x.stellen_id) === id);

  const firma = c(r.firma);
  const email = c(r.bewerbungs_email);
  const anschreiben = mehrzeilig(r.m5_anschreiben);
  const m4 = c(r.m4_status).toUpperCase();
  const m5 = c(r.m5_status).toUpperCase();

  const maengel = [];
  if (!firma) maengel.push('firma fehlt');
  if (m4 !== 'FERTIG') maengel.push('m4_status ist "' + (m4 || 'leer') + '"');
  if (m5 !== 'FERTIG') maengel.push('m5_status ist "' + (m5 || 'leer') + '"');
  if (!anschreiben) maengel.push('m5_anschreiben fehlt');
  if (!email) maengel.push('Empfaenger-E-Mail fehlt');
  else if (!istEmail(email)) maengel.push('Empfaenger-E-Mail ungueltig: ' + email);

  const dateiname = 'Vorschau_' + id.replace(/[^A-Za-z0-9._-]+/g, '_') + '.pdf';
  const pdf = pdfDateien.find(p => c(p.fileName) === dateiname);
  const pdfPfad = VORSCHAU_ORDNER + '/' + dateiname;
  if (!pdf) maengel.push('M5B-Vorschau fehlt (' + dateiname + ')');
  else if (Number(pdf.fileSize || 0) < 1000000) maengel.push('M5B-Vorschau technisch unplausibel (' + pdf.fileSize + ' Bytes)');

  if (maengel.length) { uebersprungen.push(id + ': ' + maengel.join('; ')); continue; }

  const beratung = beratungen.find(x => c(x.stellen_id) === id) || {};
  const beraterStatus = c(beratung.berater_status).toUpperCase();

  const alt = bisher.find(b => c(b.stellen_id) === id) || {};
  const entscheidungRoh = c(alt.entscheidung).toUpperCase().replace('Ä', 'AE');
  const notiz = mehrzeilig(alt.notiz);
  let freigabezeitpunkt = c(alt.freigabezeitpunkt);
  let finalPfad = c(alt.final_pdf_pfad);

  let status = 'OFFEN';
  let grund = '';
  let finalAusloesen = false;

  if (entscheidungRoh === '') {
    status = 'OFFEN';
  } else if (entscheidungRoh === 'SPAETER') {
    status = 'SPAETER';
    freigabezeitpunkt = '';
    finalPfad = '';
  } else if (entscheidungRoh === 'NEIN') {
    status = 'ABGELEHNT';
    freigabezeitpunkt = '';
    finalPfad = '';
  } else if (entscheidungRoh === 'JA') {
    const fehlt = [];
    if (!istEmail(email)) fehlt.push('gueltige Empfaenger-E-Mail');
    if (!anschreiben) fehlt.push('Anschreiben');
    if (!pdf) fehlt.push('Vorschau-PDF');
    if (beraterStatus !== 'FERTIG') fehlt.push('fertige Beratung (berater_status: '
      + (beraterStatus || 'keine Zeile im Tab M6_Berater') + ')');

    if (fehlt.length) {
      status = 'FEHLER';
      grund = 'Freigabe nicht moeglich, es fehlt: ' + fehlt.join(', ');
      freigabezeitpunkt = '';
      finalPfad = '';
    } else {
      if (!freigabezeitpunkt) freigabezeitpunkt = berlinZeit(jetzt) + ' (Europe/Berlin)';
      status = 'FREIGEGEBEN';
      finalPfad = FINAL_ORDNER + '/Bewerbung_' + id.replace(/[^A-Za-z0-9._-]+/g, '_') + '.pdf';
      // Zielpfad festhalten, aber NICHT erzeugen. Das FINAL-PDF traegt das
      // Versanddatum und entsteht erst bei der Versandfreigabe in M7.
      finalAusloesen = false;
    }
  } else {
    status = 'FEHLER';
    grund = 'Unbekannter Wert in entscheidung: "' + c(alt.entscheidung) + '". Erlaubt sind JA, NEIN, SPAETER.';
  }

  zeilen.push({
    json: {
      stellen_id: id,
      firma,
      empfaenger_email: email,
      betreff: BETREFF,
      anschreiben,
      vorschau_pdf_pfad: pdfPfad,
      entscheidung: c(alt.entscheidung),
      notiz,
      m6_status: status,
      freigabezeitpunkt,
      final_pdf_pfad: finalPfad,
      m6_fehlergrund: grund,

      _sheet_initialisiert: sheetInitialisiert,
      _berater_status: beraterStatus,

      // Schnittstelle zu M5B FINAL. Steht seit dem 10.08.2026 immer auf false:
      // M6 loest FINAL nicht mehr aus, das tut die Versandfreigabe in M7.
      _final_ausloesen: finalAusloesen,
      _m5b_modus: 'FINAL',
      _m5b_freigabe: finalAusloesen ? 'JA' : 'NEIN',
      _m5b_stellen_id: id
    }
  });
}

if (zeilen.length === 0) {
  return [{ json: { _keine_zeilen: true, _sheet_initialisiert: sheetInitialisiert, _uebersprungen: uebersprungen } }];
}
zeilen[0].json._uebersprungen = uebersprungen;
return zeilen;

let zeilen = [];
try { zeilen = $('Freigabezeilen aufbereiten').all().map(i => i.json).filter(j => j && j.stellen_id); } catch (e) {}

let schreibFehler = [];
try { schreibFehler = $('M6_Freigabe schreiben').all().filter(i => i.json && i.json.error); } catch (e) {}

const formatItems = $input.all();
const formatFehler = formatItems.filter(i => i.json && i.json.error);
let formatAntworten = 0;
try {
  const a = formatItems[0] && formatItems[0].json ? formatItems[0].json : {};
  formatAntworten = Array.isArray(a.replies) ? a.replies.length : 0;
} catch (e) {}
let formatAnfragen = 0;
try { formatAnfragen = Number($('Formatierungsanfrage bauen').first().json._anzahl_requests || 0); } catch (e) {}

let uebersprungen = [];
try {
  const erste = $('Freigabezeilen aufbereiten').first().json || {};
  uebersprungen = erste._uebersprungen || [];
} catch (e) {}

const zaehl = (s) => zeilen.filter(z => z.m6_status === s).length;

let status = 'ERFOLGREICH';
if (schreibFehler.length) status = 'SCHREIBFEHLER';
else if (formatFehler.length) status = 'FORMATIERUNGSFEHLER';
else if (zeilen.length === 0) status = 'KEINE_ZEILEN';
else if (zaehl('FEHLER') > 0) status = 'ERFOLGREICH_MIT_FEHLERN';

return [{ json: {
  workflow: 'M6 - Freigabe',
  status,
  tab: 'M6_Freigabe',
  zeilen_gesamt: zeilen.length,
  offen: zaehl('OFFEN'),
  spaeter: zaehl('SPAETER'),
  abgelehnt: zaehl('ABGELEHNT'),
  freigegeben: zaehl('FREIGEGEBEN'),
  fehler: zaehl('FEHLER'),
  schreibfehler: schreibFehler.length,
  formatierung: {
    gesendete_anfragen: formatAnfragen,
    bestaetigte_antworten: formatAntworten,
    fehler: formatFehler.length,
    umfasst: 'Rahmen, Zeilenhoehen (Kopf 30px, Daten 24px), Textumbruch CLIP, fixierte Kopfzeile, Dropdown G'
  },
  bewerbungen: zeilen.map(z => ({
    stellen_id: z.stellen_id,
    firma: z.firma,
    empfaenger: z.empfaenger_email,
    entscheidung: z.entscheidung || '(leer)',
    m6_status: z.m6_status,
    freigabezeitpunkt: z.freigabezeitpunkt || '',
    vorschau: z.vorschau_pdf_pfad
  })),
  uebersprungen,
  // Nur Zeilen mit entscheidung=JA loesen M5B FINAL aus.
  // Das Versanddatum setzt ausschliesslich M5B im FINAL-Lauf.
  m5b_final_ausgeloest_fuer: zeilen.filter(z => z._final_ausloesen === true).map(z => z.stellen_id),
  kostenpflichtige_ki_aufrufe: 0,
  versand_erfolgt: false,
  ausgefuehrt_am: new Date().toISOString()
}}];

// Baut die batchUpdate-Anfrage fuer Rahmen, Zeilenhoehen, Textumbruch,
// fixierte Kopfzeile und das Dropdown. Aendert ausschliesslich Formatierung
// und Datenvalidierung, niemals Zellwerte.

const SHEET_IDS = { Agentursuche: 208542172, M6_Freigabe: 1179898354 };
const LINIE = { style: 'SOLID', color: { red: 0.72, green: 0.72, blue: 0.72 } };

// Tatsaechlich genutzte Groesse ermitteln
function genutzt(nodeName) {
  let rows = [];
  try { rows = $(nodeName).all().map(i => i.json || {}).filter(j => Object.keys(j).length > 0); } catch (e) { return null; }
  if (!rows.length) return null;
  const spalten = new Set();
  rows.forEach(r => Object.keys(r).forEach(k => { if (k !== 'row_number') spalten.add(k); }));
  return { zeilen: rows.length, spalten: spalten.size };
}

const ag = genutzt('Agentursuche laden');
let m6 = null;
try {
  const geschrieben = $('Freigabezeilen aufbereiten').all().map(i => i.json).filter(j => j && j.stellen_id);
  if (geschrieben.length) m6 = { zeilen: geschrieben.length, spalten: 12 };
} catch (e) {}

const requests = [];

function formatiere(sheetId, zeilen, spalten, mitDropdown) {
  const gesamtZeilen = zeilen + 1; // inkl. Kopfzeile
  const bereich = { sheetId, startRowIndex: 0, endRowIndex: gesamtZeilen, startColumnIndex: 0, endColumnIndex: spalten };

  // 1. Durchgehende Rahmen innerhalb und aussen
  requests.push({ updateBorders: {
    range: bereich,
    top: LINIE, bottom: LINIE, left: LINIE, right: LINIE,
    innerHorizontal: LINIE, innerVertical: LINIE
  }});

  // 2. Textumbruch auf CLIP, damit lange Texte die Zeilenhoehe nicht sprengen.
  //    Nur wrapStrategy anfassen, Inhalte und uebrige Formate bleiben unberuehrt.
  requests.push({ repeatCell: {
    range: bereich,
    cell: { userEnteredFormat: { wrapStrategy: 'CLIP' } },
    fields: 'userEnteredFormat.wrapStrategy'
  }});

  // 3. Kopfzeile 30 Pixel
  requests.push({ updateDimensionProperties: {
    range: { sheetId, dimension: 'ROWS', startIndex: 0, endIndex: 1 },
    properties: { pixelSize: 30 },
    fields: 'pixelSize'
  }});

  // 4. Datenzeilen feste 24 Pixel
  requests.push({ updateDimensionProperties: {
    range: { sheetId, dimension: 'ROWS', startIndex: 1, endIndex: gesamtZeilen },
    properties: { pixelSize: 24 },
    fields: 'pixelSize'
  }});

  // 5. Erste Zeile fixieren
  requests.push({ updateSheetProperties: {
    properties: { sheetId, gridProperties: { frozenRowCount: 1 } },
    fields: 'gridProperties.frozenRowCount'
  }});

  // 6. Dropdown in Spalte G (entscheidung), nur Datenzeilen
  if (mitDropdown) {
    requests.push({ setDataValidation: {
      range: { sheetId, startRowIndex: 1, endRowIndex: gesamtZeilen, startColumnIndex: 6, endColumnIndex: 7 },
      rule: {
        condition: { type: 'ONE_OF_LIST', values: [
          { userEnteredValue: 'JA' },
          { userEnteredValue: 'NEIN' },
          { userEnteredValue: 'SPÄTER' }
        ]},
        showCustomUi: true,
        strict: true,
        inputMessage: 'Bitte JA, NEIN oder SPÄTER waehlen.'
      }
    }});
  }
}

if (ag) formatiere(SHEET_IDS.Agentursuche, ag.zeilen, ag.spalten, false);
if (m6) formatiere(SHEET_IDS.M6_Freigabe, m6.zeilen, m6.spalten, true);

return [{ json: {
  _body: { requests },
  _anzahl_requests: requests.length,
  _agentursuche: ag,
  _m6_freigabe: m6
}}];
